// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        // initialize so this contract becomes the owner; without this both P and M revert identically
        c.initialize();
    }

    function testFuzz_property(uint256 seed) public {
        // Wide domain: the fuzzer's seed decides the implementation address.
        // Mapping mod 2 keeps address(0) reachable with high probability
        // (the deciding value is chosen by the fuzzer, not hard-coded).
        address impl = address(uint160(seed % 2));

        vm.prank(address(this));
        bool ok;
        try c.updateRoundImplementation(payable(impl)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful update must leave a non-zero round implementation.
        // Reference: reverts on address(0) (ok=false) or stores impl != 0 -> holds.
        // Mutant: succeeds and stores address(0) when the fuzzer picks seed % 2 == 0 -> breaks.
        assertTrue(!(ok && c.roundImplementation() == address(0)));
    }
}
